import{writeFileSync,existsSync}from'node:fs';import{productionEnvironment,productionPsql}from'../scripts/lib/production-database.mjs';
const out='.verification/targeted-performance-preflight-20261025.json';if(existsSync(out))throw Error('EXISTS');const{database}=productionEnvironment(process.cwd());const raw=productionPsql(database,`begin transaction read only;set local statement_timeout='15s';select jsonb_build_object('at',clock_timestamp(),'databaseBytes',pg_database_size(current_database()),'counts',jsonb_build_object('businesses',(select count(*)from public.businesses),'patients',(select count(*)from public.patients),'appointments',(select count(*)from public.appointments),'capacityPractices',(select count(*)from public.businesses where slug like 'capacity-%'),'capacityOwners',(select count(*)from auth.users where email like 'capacity-owner-%@example.test'),'migrations',(select count(*)from supabase_migrations.schema_migrations)),'settings',(select jsonb_object_agg(name,setting)from pg_settings where name in('work_mem','shared_buffers','effective_cache_size','jit','track_io_timing','track_functions','shared_preload_libraries')),'statementStatsInfo',to_regclass('extensions.pg_stat_statements_info')is not null,'databaseReset',(select stats_reset from pg_stat_database where datname=current_database()),'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'identity',pg_get_function_identity_arguments(p.oid),'definitionMd5',md5(pg_get_functiondef(p.oid))))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname in('get_availability_catalog','get_availability_window','create_appointment_with_patient_identity','clinical_document_uploads_enabled','list_user_business_contexts')));commit;`,{application:'cita_suite_targeted_preflight',timeout:25000});const d=JSON.parse(raw);if(d.counts.capacityPractices||d.counts.capacityOwners||d.counts.migrations!==126)throw Error('UNEXPECTED_SCENARIO_STATE');writeFileSync(out,JSON.stringify(d,null,2)+'\n',{flag:'wx',mode:0o600});console.log({at:d.at,databaseBytes:d.databaseBytes,counts:d.counts,settings:d.settings,statementStatsInfo:d.statementStatsInfo,databaseResetKnown:d.databaseReset!==null,functions:d.functions.length});
